const pagePath=resolve(manifest.pagePath),coursePath=resolve(manifest.coursePath),learnerPath=resolve(manifest.learnerPath);
const sourceBefore=manifest.sources.map(p=>{const actual=pinFile(resolve(p.path));for(const k of ['git','sha256','bytes'])assert.equal(actual[k],p[k],p.path+' '+k);return actual;});
