const allowed=new Set([pathToFileURL(pagePath).href,pathToFileURL(learnerPath).href]);
async function runGroup(id,fn){const detail=await fn();receipt.groups.push({id,status:'pass',detail});save();}
async function download(selector,filename,label,expected) {
 const promised=page.waitForEvent('download',{timeout:7000});
 await page.locator(selector).click();
 const d=await promised;
 assert.equal(d.suggestedFilename(),filename);
 const path=join(out,String(receipt.downloads.length+1).padStart(2,'0')+'-'+label+'-'+filename);
 await d.saveAs(path);assert.equal(await d.failure(),null);
 const b=readFileSync(path);if(expected!==undefined)assert.deepEqual(b,Buffer.isBuffer(expected)?expected:Buffer.from(expected,'utf8'),label+' exact physical bytes');
 const record={label,filename,path,bytes:b.length,sha256:sha256(b)};receipt.downloads.push(record);save();return record;
}
async function apply(phase,raw,keyboard=false) {
 await page.locator('#linkage-phase').selectOption(phase);await page.locator('#linkage-recombination').fill(raw);
 if(keyboard){await page.locator('#linkage-apply').focus();await page.keyboard.press('Enter');}else await page.locator('#linkage-apply').click();
}
async function retired() {
 assert.equal(await page.locator('#linkage-result').isVisible(),false);assert.equal(await page.locator('#linkage-download').isDisabled(),true);
}
