 const result=await action();
 await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>resolve())));
 assert.equal(downloadEvents,before);assert.equal(await page.evaluate(()=>window.__linkageAudit.urls.filter(x=>x.kind==='create').length),urlsBefore);
