async function assertNoPageOverflow() {const v=await page.evaluate(()=>({inner:innerWidth,client:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth}));assert(v.scroll<=v.client+1,JSON.stringify(v));return v;}
try {
 browser=await chromium.launch({executablePath:'/workspace/scratch/3e50c5ad22c5/production/browser/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 receipt.runtime={node:process.version,chromium:browser.version(),platform:process.platform};
 context=await browser.newContext({acceptDownloads:true,viewport:{width:375,height:812},locale:'en-US',reducedMotion:'reduce'});
 await context.addInitScript(({fixed})=>{
