  window.Date=FixedDate;
  window.__linkageAudit={storage:[],urls:[],failNextObjectURL:false};
  for(const method of ['setItem','removeItem','clear']){const native=Storage.prototype[method];Storage.prototype[method]=function(...args){window.__linkageAudit.storage.push({api:'Storage.'+method,args:args.map(String)});return native.apply(this,args);};}
  for(const [target,name,methods] of [[globalThis.IDBFactory?.prototype,'indexedDB',['open','deleteDatabase']],[globalThis.CacheStorage?.prototype,'caches',['open','delete']]])for(const method of methods){if(!target)continue;const native=target[method];target[method]=function(...args){window.__linkageAudit.storage.push({api:name+'.'+method,args:args.map(String)});return native.apply(this,args);};}
  const cookie=Object.getOwnPropertyDescriptor(Document.prototype,'cookie');
  if(cookie?.set)Object.defineProperty(Document.prototype,'cookie',{...cookie,set(value){window.__linkageAudit.storage.push({api:'cookie',value:String(value)});return cookie.set.call(this,value);}});
  const create=URL.createObjectURL.bind(URL),revoke=URL.revokeObjectURL.bind(URL);
  URL.createObjectURL=function(blob){if(window.__linkageAudit.failNextObjectURL){window.__linkageAudit.failNextObjectURL=false;window.__linkageAudit.urls.push({kind:'injected-failure'});throw Error('Receiver-only one-shot preparation refusal');}const url=create(blob);window.__linkageAudit.urls.push({kind:'create',url,size:blob.size,type:blob.type});return url;};
  URL.revokeObjectURL=function(url){window.__linkageAudit.urls.push({kind:'revoke',url});return revoke(url);};
 },{fixed:FIXED_TIME});
 await context.route('**/*',route=>{const url=route.request().url();if(allowed.has(url)||url.startsWith('blob:')||url.startsWith('data:'))return route.continue();receipt.offOrigin.push({url,method:route.request().method()});return route.abort('blockedbyclient');});
 context.on('request',r=>receipt.requests.push({url:r.url(),method:r.method(),resourceType:r.resourceType()}));
 context.on('page',p=>{p.on('pageerror',e=>receipt.errors.push(String(e)));p.on('console',m=>{if(m.type()==='error')receipt.consoleErrors.push(m.text());});p.on('download',()=>downloadEvents++);});
 page=await context.newPage();labPage=page;page.setDefaultTimeout(6000);
 await page.goto(pathToFileURL(pagePath).href);await page.waitForLoadState('load');
