  assert.equal(await page.locator('#linkage-recombination').getAttribute('type'),'text');assert.equal(await page.locator('#linkage-recombination').getAttribute('inputmode'),'numeric');
  assert.equal(await page.locator('#linkage-learner').getAttribute('href'),'../demo.html');assert.equal(await page.locator('#linkage-guide').getAttribute('href'),'./genetic-linkage.md');
  const body=await page.locator('body').innerText();for(const assumption of ASSUMPTIONS)assert(body.includes(assumption),assumption);assert(body.includes('AaBb'));assert(body.includes('aabb'));
  originalCourse=await download('#linkage-course','genetic-linkage.json','initial-course',courseBytes);
  return {unapplied:true,course:originalCourse,concepts:deck.concepts,attribution:deck.attribution,license:deck.license};
 });
 await runGroup('G2',async()=>{
  await apply('repulsion',' 014 ');await assertCross(page,'repulsion',14);
