   receipt.injections.push({which,kind:'URL.createObjectURL one-shot throw',appliedStatePreserved:true});
   await download(which==='observation'?'#linkage-download':'#linkage-course',which==='observation'?'genetic-linkage-observation.json':'genetic-linkage.json',which+'-retry',which==='observation'?expectedObservation('repulsion',' 014 '):courseBytes);
  }
  assert.equal(sha256(readFileSync(firstObservation.path)),firstObservation.sha256);
  return {sameValueRetired:same,unannouncedEditRefused:true,refusals,accepted32Zeroes:true,invalidCourse};
 });
 await runGroup('G4',async()=>{
  const cases=[];
