  await page.locator('#linkage-download').focus();
  const promised=page.waitForEvent('download',{timeout:7000});await page.keyboard.press('Enter');const d=await promised;
  assert.equal(d.suggestedFilename(),'genetic-linkage-observation.json');const path=join(out,'keyboard-endpoint-observation.json');await d.saveAs(path);assert.equal(await d.failure(),null);const b=readFileSync(path);assert.deepEqual(b,Buffer.from(expectedObservation('repulsion','50')));
